// The site's inline editor (O55b) - generated by engine/build_pages.py, do not edit in place.
// O237 M2: the matcher and the stamp live in edit-find.js (web/test.mjs drives them; the app has copyfind.ts).
import { buildIndex, fillTemplate, stamp } from "./edit-find.js";
const BASKET_KEY = "gg-site-basket";
const armed = () => { try { return sessionStorage.getItem("gg-site-editing") === "1"; } catch { return false; } };
// O237 M2 (D-268): two more kinds - the site's string catalog (content/site-strings.yaml, every word of the frame)
// and the guides' markdown - beside the framing copy (site-copy.yaml) and the explainers.
const EMPTY = () => ({ siteCopy: {}, explainers: {}, siteStrings: {}, guides: {} });
const basket = () => { try { const b = JSON.parse(localStorage.getItem(BASKET_KEY) || "{}"); return { ...EMPTY(), ...Object.fromEntries(Object.keys(EMPTY()).map((k) => [k, b[k] || {}])) }; } catch { return EMPTY(); } };
const saveBasket = (b) => { try { localStorage.setItem(BASKET_KEY, JSON.stringify(b)); } catch { /* private mode */ } };
const basketSize = (b) => Object.keys(EMPTY()).reduce((n, k) => n + Object.keys(b[k]).length, 0);

async function config() {
  try {
    const r = await fetch(new URL("web/backend.json", import.meta.url));
    if (!r.ok) return null;
    const b = await r.json();
    return b.url && b.anonKey ? { url: b.url.replace(/\/+$/, ""), anonKey: b.anonKey } : null;
  } catch { return null; }
}
function session() {
  try { const raw = localStorage.getItem("gg-sync-session"); return raw ? JSON.parse(raw) : null; } catch { return null; }
}
async function postFn(payload) {
  const cfg = await config(); const ses = session();
  if (!cfg || !ses) return null;
  try {
    const res = await fetch(cfg.url + "/functions/v1/content-pr", {
      method: "POST",
      headers: { "content-type": "application/json", "authorization": "Bearer " + ses.access_token, "apikey": cfg.anonKey },
      body: JSON.stringify(payload),
    });
    return { status: res.status, body: await res.json().catch(() => ({})) };
  } catch { return null; }
}

const el = (tag, cls, text) => { const n = document.createElement(tag); if (cls) n.className = cls; if (text !== undefined) n.textContent = text; return n; };
let started = false, pins = {}, serverCopy = {};
// O237 M2: the catalog the pages show (edit-strings.json, written by the build), what main says the strings are
// (strings-read; null against a backend deployed before M2, which then keeps no string or guide edit), and the
// keys a suite holds. The built catalog is what the stamp matches against: it is what this page was built from.
// `live` is the catalog as this device shows it now - the built words with the basket's and the drawer's edits laid
// over - and the index is rebuilt from it on every edit, so a previewed string still resolves to its key.
let built = {}, live = {}, serverStrings = null, stringPins = {}, index = null;
const STRINGS_CACHE = "gg-site-strings";

const CHROME_CSS = `
body.sed-editing [data-copy], body.sed-editing [data-copy-key], body.sed-editing [data-explainer], body.sed-editing [data-guide] { outline: 2px dashed var(--accent); outline-offset: 3px; cursor: pointer; }
body.sed-editing [data-copy-key] [data-copy-key] { outline-offset: 1px; }
#seddrawer .alts { display: flex; flex-wrap: wrap; gap: .35rem; align-items: center; margin: .35rem 0 0; font-size: .8rem; color: var(--muted); }
#seddrawer .alts button { border: 1px solid var(--divider); background: transparent; color: var(--accent); border-radius: 999px; padding: .15rem .55rem; font: 600 .78rem ui-monospace, monospace; cursor: pointer; min-height: 32px; }
#seddrawer .warn { margin: .35rem 0 0; font-size: .8rem; color: var(--accent); }
#sedpill { position: fixed; bottom: 1rem; left: 50%; translate: -50%; z-index: 60; display: flex; gap: .15rem; align-items: center;
  background: var(--accent); color: #fff; border-radius: 999px; padding: .25rem .45rem; box-shadow: 0 2px 10px rgba(0,0,0,.3); white-space: nowrap; }
#sedpill .lbl { font: 600 .72rem ui-monospace, monospace; letter-spacing: .04em; text-transform: uppercase; padding: 0 .35rem; opacity: .85; }
#sedpill button { border: 0; cursor: pointer; background: transparent; color: #fff; font: 600 .95rem inherit; min-height: 36px; padding: 0 .55rem; border-radius: 999px; }
#sedpill button:hover { background: rgba(255,255,255,.14); }
#sedpill .cnt { background: rgba(255,255,255,.18); }
#seddrawer { position: fixed; inset: auto 0 0 0; z-index: 61; max-height: 72vh; overflow-y: auto; background: var(--surface); color: var(--text);
  border-top: 1px solid var(--divider); border-radius: .8rem .8rem 0 0; padding: .7rem .9rem 1rem; box-shadow: 0 -6px 24px rgba(0,0,0,.25); }
#seddrawer .k { margin: 0 0 .4rem; font: 600 .85rem ui-monospace, monospace; }
#seddrawer textarea { width: 100%; padding: .5rem .6rem; border: 1px solid var(--divider); border-radius: .4rem; background: var(--bg); color: var(--text); font: .95rem/1.5 inherit; resize: vertical; }
#seddrawer .pin { margin: .35rem 0 0; font-size: .8rem; color: var(--accent); }
#seddrawer .note { margin: .35rem 0 0; font-size: .8rem; color: var(--muted); }
#seddrawer .row { display: flex; gap: .5rem; justify-content: flex-end; margin-top: .7rem; }
#seddrawer .btn { display: inline-flex; align-items: center; min-height: 44px; background: var(--accent); color: #fff; border: 0; border-radius: 999px; padding: 0 1rem; font: 600 .95rem inherit; cursor: pointer; }
#seddrawer .btn.ghost { background: transparent; color: var(--accent); border: 1px solid var(--divider); }
#seddrawer .btn:disabled { opacity: .6; cursor: default; }
#seddrawer .item { display: flex; align-items: center; justify-content: space-between; gap: .6rem; border-bottom: 1px solid var(--divider); padding: .35rem 0; font-size: .95rem; }
#seddrawer .item .ik { font: 600 .85rem ui-monospace, monospace; }
#seddrawer .item small { color: var(--muted); }
#seddrawer .item .x { border: 0; background: transparent; color: var(--muted); cursor: pointer; font-size: 1.1rem; min-width: 44px; min-height: 44px; }
#seddrawer .status a { color: var(--accent); }
`;

function closeDrawer() { const d = document.getElementById("seddrawer"); if (d) d.remove(); }
function drawer(title) {
  closeDrawer();
  const d = el("div"); d.id = "seddrawer";
  d.appendChild(el("p", "k", title));
  document.body.appendChild(d);
  return d;
}

let stampTimer = 0;
function restamp() { if (!index) return; stamp(index, document.body); applyBasket(); }
function watchForRedraws() {
  // the frame's menus and sheet copy the footer's groups when they open, and the peek loads a card late: a
  // debounced pass after each redraw keeps every late word tappable (the app's editor does the same)
  new MutationObserver(() => { clearTimeout(stampTimer); stampTimer = setTimeout(restamp, 120); })
    .observe(document.body, { childList: true, subtree: true, characterData: true });
}

// A found string's live preview: every element stamped with the key is rewritten with the edited TEMPLATE filled
// with the numbers that element had; an `_html` key keeps its em/strong. The original markup is kept aside so
// Revert puts back exactly what the build wrote (a {placeholder} the page filled with a link, say).
const original = new WeakMap();
const safeHtml = (v) => v.replace(/<[^>]*>/g, (tag) => (/^<\/?(em|strong|b|i)>$/.test(tag) ? tag : ""));
function setLive(key, tpl) { live[key] = tpl; index = buildIndex(live); }
function applyLiveString(key, tpl) {
  setLive(key, tpl);
  for (const n of document.querySelectorAll('[data-copy-key="' + key + '"]')) {
    if (!original.has(n)) original.set(n, n.innerHTML);
    const fill = JSON.parse(n.dataset.copyFill || "[]");
    const v = fillTemplate(tpl, fill);
    if (key.endsWith("_html")) n.innerHTML = safeHtml(v); else n.textContent = v;
  }
}
function revertLiveString(key) {
  setLive(key, built[key]);
  for (const n of document.querySelectorAll('[data-copy-key="' + key + '"]')) if (original.has(n)) n.innerHTML = original.get(n);
}
const stringNow = (key) => (serverStrings && serverStrings[key] !== undefined ? serverStrings[key] : built[key]);

function applyLive(key, v) {
  for (const n of document.querySelectorAll('[data-copy="' + key + '"]')) n.textContent = v;
}
function applyBasket() {
  const b = basket();
  for (const k of Object.keys(b.siteCopy)) applyLive(k, b.siteCopy[k]);
  for (const k of Object.keys(b.siteStrings)) applyLiveString(k, b.siteStrings[k]);
}

function renderPill() {
  const old = document.getElementById("sedpill"); if (old) old.remove();
  const pill = el("div"); pill.id = "sedpill";
  const n = basketSize(basket());
  const cnt = el("button", "cnt", n === 1 ? "1 change" : n + " changes");
  cnt.type = "button"; cnt.addEventListener("click", basketDrawer);
  const done = el("button", "", "Done");
  done.type = "button";
  done.addEventListener("click", () => { try { sessionStorage.removeItem("gg-site-editing"); sessionStorage.removeItem(STRINGS_CACHE); } catch { /* fine */ } location.reload(); });
  pill.append(el("span", "lbl", "Editing this site"), cnt, done);
  document.body.appendChild(pill);
}

function copyDrawer(key) {
  const b = basket();
  const current = b.siteCopy[key] !== undefined ? b.siteCopy[key]
    : (serverCopy[key] !== undefined ? serverCopy[key]
      : (document.querySelector('[data-copy="' + key + '"]') || {}).textContent || "");
  const d = drawer(key);
  const area = el("textarea"); area.rows = current.length > 90 ? 4 : 2; area.value = current;
  d.appendChild(area);
  if (key in pins) d.appendChild(el("p", "pin", "Held by a check - proposing this edit opens a PR that stays red until a session moves its test."));
  d.appendChild(el("p", "note", "The page updates as you type - on this device only, until the PR merges."));
  area.addEventListener("input", () => applyLive(key, area.value));
  const row = el("div", "row");
  const revert = el("button", "btn ghost", "Revert"); revert.type = "button";
  revert.addEventListener("click", () => {
    applyLive(key, serverCopy[key] !== undefined ? serverCopy[key] : current);
    const bb = basket(); delete bb.siteCopy[key]; saveBasket(bb);
    renderPill(); closeDrawer();
  });
  const keep = el("button", "btn", "Keep in changes"); keep.type = "button";
  keep.addEventListener("click", () => {
    const v = area.value;
    if (!v.trim()) return; // an emptied string is a revert, not an edit
    const bb = basket();
    if (v === serverCopy[key]) delete bb.siteCopy[key]; else bb.siteCopy[key] = v;
    saveBasket(bb); renderPill(); closeDrawer();
  });
  row.append(revert, keep); d.appendChild(row);
  area.focus();
}

// O237 M2: a found string. The textarea holds the TEMPLATE (a `{placeholder}` the page fills stays a placeholder);
// the page previews it filled with the numbers it had. The drawer names the key it chose and offers the others
// the words belong to; a held key says so; against a backend deployed before M2 nothing can be kept.
function stringDrawer(node, key) {
  key = key || node.dataset.copyKey;
  const keys = (node.dataset.copyKeys || key).split(" ");
  const b = basket();
  const current = b.siteStrings[key] !== undefined ? b.siteStrings[key] : (stringNow(key) || "");
  const d = drawer(key);
  const area = el("textarea"); area.rows = current.length > 90 ? 4 : 2; area.value = current;
  d.appendChild(area);
  if (keys.length > 1) {
    const alts = el("p", "alts", "These words are also:");
    for (const k of keys) if (k !== key) {
      const bt = el("button", "", k); bt.type = "button";
      bt.addEventListener("click", () => { revertLiveString(key); stringDrawer(node, k); });
      alts.appendChild(bt);
    }
    d.appendChild(alts);
  }
  if (key in stringPins) d.appendChild(el("p", "pin", "Held by a check - proposing this edit opens a PR that stays red until a session moves its test."));
  if (node.dataset.copyFill) d.appendChild(el("p", "note", "A {placeholder} is filled by the page - keep it where the number or name should go."));
  d.appendChild(el("p", "note", "The page updates as you type - on this device only, until the PR merges. Spanish readers see the new English until the string is translated again."));
  const old = serverStrings === null;
  if (old) d.appendChild(el("p", "warn", "The site's backend has not been redeployed for string edits yet (supabase functions deploy content-pr, or the deploy-content-pr workflow once its secret exists). Nothing can be kept until it is."));
  area.addEventListener("input", () => applyLiveString(key, area.value));
  const row = el("div", "row");
  const revert = el("button", "btn ghost", "Revert"); revert.type = "button";
  revert.addEventListener("click", () => {
    revertLiveString(key);
    const bb = basket(); delete bb.siteStrings[key]; saveBasket(bb);
    renderPill(); closeDrawer();
  });
  const keep = el("button", "btn", "Keep in changes"); keep.type = "button"; keep.disabled = old;
  keep.addEventListener("click", () => {
    const v = area.value;
    if (!v.trim() || old) return;
    const bb = basket();
    if (v === stringNow(key)) delete bb.siteStrings[key]; else bb.siteStrings[key] = v;
    saveBasket(bb); renderPill(); closeDrawer();
  });
  row.append(revert, keep); d.appendChild(row);
  area.focus();
}

// An explainer's or a guide's markdown (O237 M2 added the guides: the same drawer, `guide-read`, the `guides` kind).
function proseDrawer(kind, slug) { return kind === "guide" ? markdownDrawer("guide", "guides", slug) : markdownDrawer("explainer", "explainers", slug); }
function markdownDrawer(kind, bucket, slug) {
  const d = drawer(kind + ": " + slug);
  const area = el("textarea"); area.rows = 12; area.value = "Loading…"; area.disabled = true;
  d.appendChild(area);
  d.appendChild(el("p", "note", "The markdown behind this page. The rendered page updates when the PR merges and the site rebuilds."));
  const row = el("div", "row");
  const cancel = el("button", "btn ghost", "Cancel"); cancel.type = "button";
  cancel.addEventListener("click", closeDrawer);
  const old = kind === "guide" && serverStrings === null;
  if (old) d.appendChild(el("p", "warn", "The site's backend has not been redeployed for guide edits yet (supabase functions deploy content-pr, or the deploy-content-pr workflow once its secret exists). Nothing can be kept until it is."));
  const keep = el("button", "btn", "Keep in changes"); keep.type = "button"; keep.disabled = true;
  keep.addEventListener("click", () => {
    if (area.value.trim() && !old) { const bb = basket(); bb[bucket][slug] = area.value; saveBasket(bb); }
    renderPill(); closeDrawer();
  });
  row.append(cancel, keep); d.appendChild(row);
  const prior = basket()[bucket][slug];
  if (prior !== undefined) { area.value = prior; area.disabled = false; keep.disabled = old; return; }
  if (old) { area.value = ""; area.disabled = true; return; }
  postFn({ mode: kind + "-read", slug }).then((r) => {
    if (r && typeof r.body.markdown === "string") { area.value = r.body.markdown; area.disabled = false; keep.disabled = false; }
    else area.value = r ? "Could not load: " + (r.body.error || r.status) : "Network error.";
  });
}

function basketDrawer() {
  const b = basket();
  const n = basketSize(b);
  const d = drawer(n === 1 ? "1 change" : n + " changes");
  const list = el("div"); d.appendChild(list);
  const item = (label, sub, remove) => {
    const row = el("div", "item");
    const left = el("span");
    left.appendChild(el("span", "ik", label));
    left.appendChild(document.createElement("br"));
    left.appendChild(el("small", "", sub));
    const x = el("button", "x", "×"); x.type = "button";
    x.addEventListener("click", () => { remove(); renderPill(); closeDrawer(); if (basketSize(basket())) basketDrawer(); });
    row.append(left, x); list.appendChild(row);
  };
  for (const k of Object.keys(b.siteCopy)) item(k, '"' + b.siteCopy[k].slice(0, 44) + '"', () => {
    applyLive(k, serverCopy[k] !== undefined ? serverCopy[k] : "");
    const bb = basket(); delete bb.siteCopy[k]; saveBasket(bb);
  });
  for (const k of Object.keys(b.siteStrings)) item(k, '"' + b.siteStrings[k].slice(0, 44) + '"', () => {
    revertLiveString(k);
    const bb = basket(); delete bb.siteStrings[k]; saveBasket(bb);
  });
  for (const slug of Object.keys(b.explainers)) item("explainer: " + slug, "edited text", () => {
    const bb = basket(); delete bb.explainers[slug]; saveBasket(bb);
  });
  for (const slug of Object.keys(b.guides)) item("guide: " + slug, "edited text", () => {
    const bb = basket(); delete bb.guides[slug]; saveBasket(bb);
  });
  if (!n) list.appendChild(el("p", "note", "Nothing kept yet - tap any outlined element to edit it."));
  const status = el("p", "status");
  const row = el("div", "row");
  const back = el("button", "btn ghost", "Keep editing"); back.type = "button";
  back.addEventListener("click", closeDrawer);
  const propose = el("button", "btn", "Propose all as one PR"); propose.type = "button";
  propose.disabled = n === 0;
  propose.addEventListener("click", async () => {
    propose.disabled = true;
    status.textContent = "Opening a pull request…";
    const bb = basket();
    const r = await postFn({ mode: "changeset", siteCopy: bb.siteCopy, explainers: bb.explainers, siteStrings: bb.siteStrings, guides: bb.guides });
    status.replaceChildren();
    if (r && r.body.prUrl) {
      status.append("Pull request opened - nothing is live until you merge it. ");
      const a = el("a", "", "Review the PR"); a.href = r.body.prUrl; a.target = "_blank"; a.rel = "noreferrer";
      status.appendChild(a);
      saveBasket(EMPTY());
      renderPill();
    } else if (r && r.status === 403) {
      status.textContent = "This account is not the maintainer - the server refused the write.";
      propose.disabled = false;
    } else {
      status.textContent = r ? "Could not open the PR: " + (r.body.error || r.status) : "Network error.";
      propose.disabled = false;
    }
  });
  row.append(back, propose);
  d.append(status, row);
}

function intercept(e) {
  const t = e.target;
  if (!t || !(t instanceof Element)) return;
  if (t.closest("#seddrawer") || t.closest("#sedpill")) return; // the chrome itself works normally
  const prose = t.closest("[data-explainer],[data-guide]");
  // the nearest stamp wins: a render site's own (data-copy) or the one the matcher made (data-copy-key)
  const hit = t.closest("[data-copy],[data-copy-key]");
  if (!prose && !hit) return;
  e.preventDefault();
  e.stopPropagation();
  if (hit && hit.dataset.copy !== undefined) copyDrawer(hit.getAttribute("data-copy"));
  else if (hit) stringDrawer(hit);
  else if (prose.dataset.guide !== undefined) proseDrawer("guide", prose.getAttribute("data-guide"));
  else proseDrawer("explainer", prose.getAttribute("data-explainer"));
}

async function boot(loud) {
  if (started) return;
  const r = await postFn({ mode: "copy-read", copyFile: "site" });
  if (!r || !r.body.copy) {
    // Arming is passive on an armed session's navigation, so a quiet failure must stay quiet -
    // but an EXPLICIT #edit entry gets told what happened, same register as the app's editor.
    if (loud) alert(r && r.status === 403
      ? "This account is not the maintainer - editing is maintainer-only."
      : "Editing needs the backend and a signed-in session (sign in from the app first).");
    return;
  }
  started = true;
  try { sessionStorage.setItem("gg-site-editing", "1"); } catch { /* fine */ }
  try { localStorage.setItem("gg-editor", "1"); } catch { /* fine */ }
  pins = r.body.pins || {};
  serverCopy = r.body.copy || {};
  const style = document.createElement("style"); style.textContent = CHROME_CSS; document.head.appendChild(style);
  document.body.classList.add("sed-editing");
  applyBasket();
  renderPill();
  document.addEventListener("click", intercept, true);
  // O237 M2: the catalog this page was built from, and what main says the strings are (once a session; a backend
  // deployed before M2 answers neither strings-read nor guide-read, and then no string or guide edit is kept)
  const [cat, srv] = await Promise.all([
    fetch(new URL("edit-strings.json", import.meta.url)).then((x) => (x.ok ? x.json() : {})).catch(() => ({})),
    readServerStrings(),
  ]);
  built = cat || {};
  live = { ...built };
  serverStrings = srv ? srv.strings : null;
  stringPins = (srv && srv.pins) || {};
  index = buildIndex(live);
  restamp();
  watchForRedraws();
}

async function readServerStrings() {
  try { const c = sessionStorage.getItem(STRINGS_CACHE); if (c) return JSON.parse(c); } catch { /* fine */ }
  const r = await postFn({ mode: "strings-read" });
  const v = r && r.status === 200 && r.body && r.body.strings ? { strings: r.body.strings, pins: r.body.pins || {} } : null;
  try { if (v) sessionStorage.setItem(STRINGS_CACHE, JSON.stringify(v)); } catch { /* fine */ }
  return v;
}

if (location.hash === "#edit") boot(true);
else if (armed()) boot(false);
window.addEventListener("hashchange", () => { if (location.hash === "#edit") boot(true); });
